/**
 * Brings a deleted workspace back to life, within the retention window. There
 * is no `Actor` to authorize with — a deleted org cannot be signed into — so
 * the caller is identified by user id and the role is read straight off their
 * membership row.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Organization", orgId);
  }

  if (org.archivedAt === null) {
    return org;
  }

  const windowEnd = new Date(org.archivedAt).getTime() +
    DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
  if (Date.now() >= windowEnd) {
    throw new NotFoundError("Organization", orgId);
  }

  assertCan(
    { userId, orgId, role: member.role },
    "org:restore",
    orgResource(orgId),
  );

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(orgId, userId),
    slug: restored.slug,
  });

  return restored;
}

