import { afterAll, beforeAll, describe, expect, it } from "vitest";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgService from "@/server/services/organization-service";
import { PermissionDeniedError } from "@/lib/permissions";
import { NotFoundError } from "@/server/services/_support";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { subscribe } from "@/lib/event-bus";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("scratch");
});

afterAll(() => {
  cleanup();
});

describe("scratch: delete/restore/purge", () => {
  it("deletes, restores, and enforces permissions", async () => {
    const deletedEvents: unknown[] = [];
    const restoredEvents: unknown[] = [];
    subscribe("organization.deleted", (p) => { deletedEvents.push(p); });
    subscribe("organization.restored", (p) => { restoredEvents.push(p); });

    const deleted = await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    expect(deleted.archivedAt).not.toBeNull();
    expect(deletedEvents).toHaveLength(1);

    // double delete -> AlreadyArchivedError
    await expect(
      orgService.deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).rejects.toThrow(AlreadyArchivedError);

    // non-member restore -> NotFoundError
    await expect(
      orgService.restoreOrganization(("nonexistent-user" as never), tenant.org.id),
    ).rejects.toThrow(NotFoundError);

    // non-owner member restore -> PermissionDeniedError
    await expect(
      orgService.restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toThrow(PermissionDeniedError);

    // owner restores successfully
    const restored = await orgService.restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(restored.archivedAt).toBeNull();
    expect(restoredEvents).toHaveLength(1);

    // restoring an already-live org is a no-op, no new event
    const again = await orgService.restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(again.archivedAt).toBeNull();
    expect(restoredEvents).toHaveLength(1);
  });

  it("throws NotFoundError once the retention window has closed, and purge removes everything", async () => {
    const deleted = await orgService.deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });

    const farFuture = new Date(
      new Date(deleted.archivedAt!).getTime() + 31 * 24 * 60 * 60 * 1000,
    );

    // simulate time passing past the window without running the purge job
    const realNow = Date.now;
    Date.now = () => farFuture.getTime();
    try {
      await expect(
        orgService.restoreOrganization(tenant.userIds.owner, tenant.org.id),
      ).rejects.toThrow(NotFoundError);
    } finally {
      Date.now = realNow;
    }

    const result = await runCleanupArchivedJob(farFuture);
    expect(result.processed).toBeGreaterThan(0);

    const gone = await orgRepo.findOrgById(tenant.org.id);
    expect(gone).toBeNull();

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    expect(member).toBeNull();

    await expect(
      orgService.restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toThrow(NotFoundError);
  });
});

