/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNotNull, isNull, like, lte } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch, restorePatch } from "@/lib/soft-delete";
import {
  activityEvents,
  attachments,
  comments,
  getDb,
  invitations,
  invoices,
  issueLabels,
  issues,
  labels,
  members,
  notificationPreferences,
  notifications,
  organizationUsage,
  organizations,
  projectMembers,
  projects,
  searchIndex,
  sessions,
  subscriptions,
  webhookDeliveries,
  webhookEndpoints,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  return row ? toOrganization(row) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

export async function restoreOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(restorePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/**
 * Workspaces deleted at or before `cutoff` — the retention sweep's purge
 * candidates, whatever the plan's own archived-row retention says.
 */
export async function listOrgIdsArchivedBefore(
  cutoff: IsoTimestamp,
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(
      and(isNotNull(organizations.archivedAt), lte(organizations.archivedAt, cutoff)),
    )
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.id));
}

/**
 * Permanently removes a deleted workspace and every row that belongs to it.
 * Sessions that were pointed at it simply lose their active workspace rather
 * than being destroyed — user accounts are never touched by this.
 */
export async function purgeOrganization(orgId: OrgId): Promise<void> {
  const db = getDb();

  db.delete(issueLabels).where(orgPredicate(issueLabels.orgId, orgId)).run();
  db.delete(attachments).where(orgPredicate(attachments.orgId, orgId)).run();
  db.delete(comments).where(orgPredicate(comments.orgId, orgId)).run();
  db.delete(labels).where(orgPredicate(labels.orgId, orgId)).run();
  db.delete(issues).where(orgPredicate(issues.orgId, orgId)).run();
  db.delete(projectMembers).where(orgPredicate(projectMembers.orgId, orgId)).run();
  db.delete(projects).where(orgPredicate(projects.orgId, orgId)).run();
  db.delete(invitations).where(orgPredicate(invitations.orgId, orgId)).run();
  db.delete(members).where(orgPredicate(members.orgId, orgId)).run();
  db.delete(notifications).where(orgPredicate(notifications.orgId, orgId)).run();
  db.delete(notificationPreferences)
    .where(orgPredicate(notificationPreferences.orgId, orgId))
    .run();
  db.delete(activityEvents).where(orgPredicate(activityEvents.orgId, orgId)).run();
  db.delete(invoices).where(orgPredicate(invoices.orgId, orgId)).run();
  db.delete(subscriptions).where(orgPredicate(subscriptions.orgId, orgId)).run();
  db.delete(webhookDeliveries)
    .where(orgPredicate(webhookDeliveries.orgId, orgId))
    .run();
  db.delete(webhookEndpoints).where(orgPredicate(webhookEndpoints.orgId, orgId)).run();
  db.delete(searchIndex).where(orgPredicate(searchIndex.orgId, orgId)).run();
  db.delete(organizationUsage).where(eq(organizationUsage.orgId, orgId)).run();

  db.update(sessions)
    .set({ activeOrgId: null })
    .where(eq(sessions.activeOrgId, orgId))
    .run();

  db.delete(organizations).where(eq(organizations.id, orgId)).run();
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}
